    Bug 2017206 - Avoid concatenating localized strings, allow the localizer to define sentence placement. r=aleca,tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D306301

diff --git a/mail/extensions/am-e2e/am-e2e.js b/mail/extensions/am-e2e/am-e2e.js
index aeb70d8a367..a65570079c8 100644
--- a/mail/extensions/am-e2e/am-e2e.js
+++ b/mail/extensions/am-e2e/am-e2e.js
@@ -712,7 +712,7 @@ async function smimeSelectCert(id) {
         let failureText;
         if (verifyResult.isNssError) {
           failureText = await document.l10n.formatValue(
-            "configured-cert-failure-detail",
+            "configured-cert-failure-use-anyway-detail",
             {
               errorMsg: verifyResult.errorMsg,
               errorCodeStr: verifyResult.errorName,
@@ -720,16 +720,13 @@ async function smimeSelectCert(id) {
           );
         } else {
           failureText = await document.l10n.formatValue(
-            "configured-cert-failure",
+            "configured-cert-failure-use-anyway",
             { errorCode: verifyResult.errorCode }
           );
         }
-        const useAnyway = await document.l10n.formatValue(
-          "configured-cert-use-anyway"
-        );
         // Let the user override: a local-only failure can be a false
         // negative, e.g. an issuer CA not yet installed.
-        if (!askUser(`${failureText}\n\n${useAnyway}`)) {
+        if (!askUser(failureText)) {
           return;
         }
       }
diff --git a/mail/locales/en-US/messenger/smime/smime.ftl b/mail/locales/en-US/messenger/smime/smime.ftl
index 13512df6f78..932ef41c464 100644
--- a/mail/locales/en-US/messenger/smime/smime.ftl
+++ b/mail/locales/en-US/messenger/smime/smime.ftl
@@ -16,6 +16,9 @@ configured-cert-failure-detail = The certificate verification failed with the fo
 # $errorCode A numeric error code
 configured-cert-failure = The certificate verification failed with error code { $errorCode }

-# Shown in a confirmation dialog after an S/MIME certificate the user just
-# selected fails verification, offering to use it regardless.
-configured-cert-use-anyway = Do you want to use this certificate anyway?
+# $errorMsg A sentence that explains the error.
+# $errorCodeStr A human readable error code, e.g. SEC_ERROR_UNKNOWN_ISSUER
+configured-cert-failure-use-anyway-detail = There is a problem with this certificate. Would you like to use it anyway? Certificate verification failed with the following error: { $errorMsg } (Error Code: { $errorCodeStr })
+
+# $errorCode A numeric error code
+configured-cert-failure-use-anyway = There is a problem with this certificate. Would you like to use it anyway? Certificate verification failed with error code { $errorCode }
